const BOARD_VERSION=2;
const KEY_HALVES=['tooth','loop','tooth','loop','tooth','loop'];
// Tooth shrines: Tempoross 5 KC. Loop shrines: Wintertodt 5 KC.
const SPECIAL_KC=5;
const VAULT_REQUIREMENT='Obtain any purple (unique reward) from The Fractured Archive.';
let keyProgress={};
const INLINE_ART={'vault-sigil.svg':'data:image/svg+xml;base64,','tooth.png':'data:image/png;base64,','loop.png':'data:image/png;base64,','archive-key.png':'data:image/png;base64,'};
const SVG_NS='http://www.w3.org/2000/svg';
const colors=['#df4d4d','#4287e7','#46a66b','#b06ce3','#ee903d','#31b7bf'];
const teamNames=['Crimson','Azure','Verdant','Violet','Ember','Cyan'];
const HIDDEN={boss:'Unknown Challenge',drop:'Control an adjacent active tile to reveal this challenge.',difficulty:0};
let teamCount=Number(localStorage.getItem('xodus-archive-v2-team-count')||4),viewTeam=Number(localStorage.getItem('xodus-archive-v2-view-team')||0),organizer=false,authTeam=null,selected=null,challengeMap={},teamChallengeUnsubscribe=null;
let claims=JSON.parse(localStorage.getItem('xodus-archive-v2-claims')||'{}');
let actionStack=JSON.parse(localStorage.getItem('xodus-archive-v2-actions')||'[]'),eventLog=JSON.parse(localStorage.getItem('xodus-archive-v2-event-log')||'[]'),setupLocked=localStorage.getItem('xodus-archive-v2-setup-locked')==='true';
let view={x:0,y:0,scale:1},drag=null;
const $=id=>document.getElementById(id), board=$('board'), viewport=$('viewport');

function axialDistance(q,r){return Math.max(Math.abs(q),Math.abs(r),Math.abs(-q-r));}
function angleOf(q,r){return Math.atan2(Math.sqrt(3)*(r+q/2),1.5*q)}
function coordKey(q,r){return `${q},${r}`}
function angleDistance(a,b){let d=Math.abs(a-b)%(Math.PI*2);return Math.min(d,Math.PI*2-d)}
function directness(cell){const baseAngles=teamBases().map(b=>angleOf(b.q,b.r));const nearest=Math.min(...baseAngles.map(a=>angleDistance(cell.angle,a)));const halfGap=Math.PI/teamCount;return 1-Math.min(1,nearest/halfGap)}
function isCornerCoord(q,r){return [[8,0],[0,8],[-8,8],[-8,0],[0,-8],[8,-8]].some(([cq,cr])=>q===cq&&r===cr)}
function zone(d,q,r){return d===0?'vault':isCornerCoord(q,r)?'key':d<=4?'inner':d<=6?'middle':'outer';}
function shortBoss(name){return name.replace('The Fractured Archive','TFA').replace('Corrupted Gauntlet','Gauntlet').replace('Phantom Muspah','Muspah').replace('Corporeal Beast or The Nightmare','Corp / Nightmare').replace('General ','G. ').replace('Commander ','C. ').replace('Corporeal Beast','Corp').replace('Dagannoth Kings','DKs').replace('God Wars Dungeon','GWD').replace('Tombs of Amascut','ToA').replace('Theatre of Blood','ToB').replace('Chambers of Xeric','CoX').replace('Perilous Moons','Moons').slice(0,16)}
function teamBases(){const candidates=[[4,4],[-4,8],[-8,4],[-4,-4],[4,-8],[8,-4]].map(([q,r])=>({q,r}));return Array.from({length:teamCount},(_,i)=>candidates[Math.floor(i*candidates.length/teamCount)]);}
function buildTiles(){
 const coords=[];for(let q=-8;q<=8;q++)for(let r=-8;r<=8;r++){const d=axialDistance(q,r);if(d<=8)coords.push({q,r,d,angle:angleOf(q,r)})}
 coords.sort((a,b)=>a.d-b.d||a.angle-b.angle);
 const placed=new Map();
 coords.forEach(cell=>{
  const id=`H${String(placed.size+1).padStart(3,'0')}`,challenge=challengeMap[id]||HIDDEN;
  const tier=zone(cell.d,cell.q,cell.r);
  const half=cell.d===8&&isCornerCoord(cell.q,cell.r)?KEY_HALVES[[[8,0],[0,8],[-8,8],[-8,0],[0,-8],[8,-8]].findIndex(([q,r])=>q===cell.q&&r===cell.r)]:null;
  const special=tier==='vault'?{boss:'The Fractured Archive',drop:VAULT_REQUIREMENT,difficulty:5}:half?{boss:half==='tooth'?'Tempoross':'Wintertodt',drop:`Earn ${SPECIAL_KC} KC at ${half==='tooth'?'Tempoross':'Wintertodt'} · Earn ${half==='tooth'?'Tooth Half':'Loop Half'}`,difficulty:3}:challenge;
  const tile={id,q:cell.q,r:cell.r,d:cell.d,tier,boss:special.boss,drop:special.drop,difficulty:special.difficulty||0,directness:cell.d?directness(cell):1};
  placed.set(coordKey(cell.q,cell.r),tile);
 });
 return [...placed.values()];
}
let tiles=buildTiles();
function ownerFor(tile){const owner=claims[tile.id]?.team;return Number.isInteger(owner)&&owner<teamCount?owner:null;}
function neighbors(t){return [[1,0],[-1,0],[0,1],[0,-1],[1,-1],[-1,1]].map(([dq,dr])=>tiles.find(x=>x.q===t.q+dq&&x.r===t.r+dr)).filter(Boolean)}
function activeSet(team){const base=teamBases()[team];if(!base)return new Set();const start=tiles.find(t=>t.q===base.q&&t.r===base.r);const seen=new Set([start.id]),queue=[start];while(queue.length){const t=queue.shift();for(const n of neighbors(t))if(!seen.has(n.id)&&ownerFor(n)===team){seen.add(n.id);queue.push(n)}}return seen}
function isBase(tile){return teamBases().some(b=>b.q===tile.q&&b.r===tile.r)}
function isKey(tile){return tile?.tier==='key'}
function keyHalf(tile){if(!isKey(tile))return null;const corners=[[8,0],[0,8],[-8,8],[-8,0],[0,-8],[8,-8]];return KEY_HALVES[corners.findIndex(([q,r])=>tile.q===q&&tile.r===r)]||null}
// Key-shrine requirements are revealed only when the signed-in team reaches
// (owns or has active territory adjacent to) that shrine. Organizer sees all.
function canRevealKey(tile){
 if(!isKey(tile))return true;
 if(organizer)return true;
 if(authTeam===null)return false;
 return ownerFor(tile)===authTeam||neighbors(tile).some(n=>activeSet(authTeam).has(n.id));
}
function keyChallengeVisible(tile){return !isKey(tile)||canRevealKey(tile)}
function progress(team){return keyProgress[team]||{tooth:false,loop:false,assembled:false}}
function teamHasKey(team){return !!progress(team).assembled}
function awardKeyHalf(tile,team){
 const half=keyHalf(tile);if(!half||team<0||team>=teamCount)return;
 keyProgress[team]={...progress(team),[half]:true};
}
function recomputeKeyProgress(){
 // Existing saved rewards remain independent of ownership, removal, and undo.
 // Backfill only from recorded capture history for migration from earlier prototypes.
 for(const [id,claim] of Object.entries(claims)){
  const tile=tiles.find(t=>t.id===id);if(!keyHalf(tile))continue;
  const history=Array.isArray(claim.history)&&claim.history.length?claim.history:[claim];
  for(const entry of history)if(Number.isInteger(entry.team)&&entry.team<teamCount)awardKeyHalf(tile,entry.team);
 }
}
function isEligible(tile,team){if(!tile||team<0||team>=teamCount||isBase(tile)||ownerFor(tile)===team)return false;if(tile.tier==='vault'&&!teamHasKey(team))return false;const active=activeSet(team);return neighbors(tile).some(n=>active.has(n.id))}
function eligibleSet(team){return new Set(tiles.filter(t=>isEligible(t,team)).map(t=>t.id))}
function bytesFromBase64url(value){const base64=value.replace(/-/g,'+').replace(/_/g,'/').padEnd(Math.ceil(value.length/4)*4,'=');return Uint8Array.from(atob(base64),c=>c.charCodeAt(0))}
async function decryptChallengeManifest(secret){const raw=bytesFromBase64url(SECRET_BLOB),key=await crypto.subtle.importKey('raw',bytesFromBase64url(secret),{name:'AES-GCM'},false,['decrypt']),sealed=new Uint8Array(raw.length-12);sealed.set(raw.slice(28));sealed.set(raw.slice(12,28),raw.length-28);const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:raw.slice(0,12),tagLength:128},key,sealed);return JSON.parse(new TextDecoder().decode(plain))}

// Map the existing encrypted raid objectives ONE tier inward, then install the GWD ring.
// The existing sealed manifest is never modified. This mapping is applied after the organizer
// decrypts it and then shared via the normal team reveal documents.
function applyGwdRaidProgression(original){
 const result={...original};
 const coords=[];
 for(let q=-8;q<=8;q++)for(let r=-8;r<=8;r++){
  const d=axialDistance(q,r);if(d<=8)coords.push({q,r,d,angle:angleOf(q,r)});
 }
 coords.sort((a,b)=>a.d-b.d||a.angle-b.angle);
 const cells=coords.map((c,i)=>({...c,id:`H${String(i+1).padStart(3,'0')}`}));
 // Raid challenges originally sit at d=2 (CoX), d=3 (ToB), d=4 (ToA).
 // Preserve actual boss/drop combinations, relocating them by nearest angle.
 for(let distance=1;distance<=3;distance++){
  const oldRing=cells.filter(c=>c.d===distance+1);
  for(const target of cells.filter(c=>c.d===distance)){
   const closest=oldRing.reduce((best,c)=>angleDistance(c.angle,target.angle)<angleDistance(best.angle,target.angle)?c:best);
   if(original[closest.id])result[target.id]={...original[closest.id]};
  }
 }
 // d=4 has 24 physical hexes, so each of six 60-degree approaches has four cells.
 // A five-boss menu cannot be repeated six times without adding hexes. Place Nex on
 // the central approach in every sector, with the other four encounters across its flanks.
 const gwd=[
  {boss:"K'ril Tsutsaroth",drop:'Obtain a staff of the dead.',difficulty:4},
  {boss:'General Graardor',drop:'Obtain a Bandos chestplate OR Bandos tassets.',difficulty:4},
  {boss:'Nex',drop:'Obtain any Torva armour piece (full helm, platebody, or platelegs).',difficulty:5},
  {boss:"Kree'arra",drop:'Obtain an Armadyl chestplate OR Armadyl chainskirt.',difficulty:4},
  {boss:'Commander Zilyana',drop:'Obtain an Armadyl crossbow.',difficulty:4}
 ];
 const ring=cells.filter(c=>c.d===4);
 for(const tile of ring){
  // Centerline = the closest of six team directions, independent of team count.
  const theta=((tile.angle%(2*Math.PI))+2*Math.PI)%(2*Math.PI);
  const sector=Math.round(theta/(Math.PI/3))%6;
  const center=sector*Math.PI/3;
  let delta=theta-center;if(delta>Math.PI)delta-=2*Math.PI;if(delta< -Math.PI)delta+=2*Math.PI;
  // One Nex path per sector. The other boss options alternate across neighboring sectors.
  let slot;
  if(Math.abs(delta)<.15)slot=2;
  else if(delta<-.29)slot=sector%2?0:1;
  else if(delta<0)slot=1;
  else if(delta>.29)slot=sector%2?4:3;
  else slot=3;
  result[tile.id]={...gwd[slot]};
 }
 return result;
}

function refreshChallenges(){tiles=buildTiles();if(selected)selected=tiles.find(t=>t.id===selected.id)||null;if(selected)selectTile(selected);else render()}
async function loadOrganizerChallenges(){
 try{const snapshot=await getDoc(doc(db,'events',EVENT_ID,'private','config'));if(!snapshot.exists()||!snapshot.data().boardKey)throw new Error('Missing board key');challengeMap=applyGwdRaidProgression(await decryptChallengeManifest(snapshot.data().boardKey));refreshChallenges();await publishTeamReveals();syncStatus('Live · organizer','online')}
 catch(error){console.error(error);challengeMap={};refreshChallenges();syncStatus('Security setup needed','error');toast('Add the private board key in Firebase to unlock organizer challenges')}
}
function subscribeTeamChallenges(team){if(teamChallengeUnsubscribe)teamChallengeUnsubscribe();teamChallengeUnsubscribe=onSnapshot(doc(db,'events',EVENT_ID,'teams',`team${team+1}`),snapshot=>{challengeMap=snapshot.exists()&&snapshot.data().boardVersion===BOARD_VERSION?snapshot.data().challenges||{}:{};refreshChallenges();syncStatus(`Live · Team ${teamNames[team]}`,'online')},error=>{console.error(error);challengeMap={};refreshChallenges();syncStatus('Team view unavailable','error')})}
async function publishTeamReveals(){
 if(!organizer||!Object.keys(challengeMap).length)return;
 await Promise.all(TEAM_ACCOUNTS.map(async(account,team)=>{const active=activeSet(team),visible=new Set(tiles.filter(t=>ownerFor(t)===team).map(t=>t.id));for(const t of tiles)if(neighbors(t).some(n=>active.has(n.id)))visible.add(t.id);const challenges=Object.fromEntries([...visible].filter(id=>challengeMap[id]).map(id=>[id,challengeMap[id]]));await setDoc(doc(db,'events',EVENT_ID,'teams',`team${team+1}`),{boardVersion:BOARD_VERSION,team,uid:account.uid,challenges,updatedAt:serverTimestamp()},{merge:true})}))
}
