onAuthStateChanged(auth,async user=>{if(teamChallengeUnsubscribe){teamChallengeUnsubscribe();teamChallengeUnsubscribe=null}organizer=false;authTeam=null;challengeMap={};if(!user){setOrganizerMode(false);refreshChallenges();updateIdentityUI();return}if(user.uid===ORGANIZER_UID){setOrganizerMode(true);updateIdentityUI();await loadOrganizerChallenges();toast('Organizer controls unlocked');return}const team=TEAM_ACCOUNTS.findIndex(account=>account.uid===user.uid);if(team>=0){authTeam=team;viewTeam=team;localStorage.setItem('xodus-archive-v2-view-team',team);$('viewTeam').value=team;setOrganizerMode(false);updateIdentityUI();subscribeTeamChallenges(team);toast(`Signed in as Team ${teamNames[team]}`);return}await signOut(auth);$('loginError').textContent='This account is not assigned to the event.'});
onSnapshot(eventRef,snapshot=>{
 if(snapshot.exists()){
  const data=snapshot.data(),compatible=data.boardVersion===BOARD_VERSION;teamCount=Number(data.teamCount||4);claims=compatible?data.claims||{}:{};keyProgress=compatible?data.keyProgress||{}:{};actionStack=compatible?data.actionStack||[]:[];eventLog=compatible?data.eventLog||[]:[];setupLocked=compatible&&!!data.setupLocked;viewTeam=Math.min(viewTeam,teamCount-1);tiles=buildTiles();recomputeKeyProgress();$('teamCount').value=teamCount;localStorage.setItem('xodus-archive-v2-team-count',teamCount);localStorage.setItem('xodus-archive-v2-claims',JSON.stringify(claims));localStorage.setItem('xodus-archive-v2-actions',JSON.stringify(actionStack));localStorage.setItem('xodus-archive-v2-event-log',JSON.stringify(eventLog));localStorage.setItem('xodus-archive-v2-setup-locked',setupLocked);if(selected)selected=tiles.find(t=>t.id===selected.id)||null;renderHistory();if(selected)selectTile(selected);else render();
 }else{
  teamCount=4;viewTeam=Math.min(viewTeam,3);claims={};actionStack=[];eventLog=[];keyProgress={};setupLocked=false;tiles=buildTiles();recomputeKeyProgress();$('teamCount').value=teamCount;localStorage.removeItem('xodus-archive-v2-claims');localStorage.removeItem('xodus-archive-v2-actions');localStorage.removeItem('xodus-archive-v2-event-log');localStorage.removeItem('xodus-archive-v2-setup-locked');renderHistory();render();
 }
 syncStatus('Live · connected','online');
},error=>{console.error(error);syncStatus('Offline · retrying','error')});
window.addEventListener('resize',fit);fit();

/* Xodus Archive: self-contained orthographic 3D renderer. No network, WebGL, or third-party dependencies. */
(() => {
 const canvas=document.getElementById('archive3d');if(!canvas)return;
 const ctx=canvas.getContext('2d',{alpha:true});if(!ctx)return;
 const TWO=Math.PI*2;
 const cam={yaw:-.33,elevation:.79,zoom:1,shiftX:0,shiftY:0};
 const initial={yaw:-.33,elevation:.79};
 const radii={outer:27,middle:27,inner:27,key:27,vault:27};
 const tints={outer:'#535b46',middle:'#706e5a',inner:'#847f68',key:'#658b81',vault:'#745488'};
 let visiblePolys=[],lastW=0,lastH=0,frame=0,drag3=null;
 const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
 const rgb=(hex)=>{let h=hex.replace('#','');if(h.length===3)h=[...h].map(c=>c+c).join('');return [0,2,4].map(i=>parseInt(h.substring(i,i+2),16))};
 const blend=(a,b,p)=>{let A=rgb(a),B=rgb(b);return `rgb(${A.map((v,i)=>Math.round(v+(B[i]-v)*p)).join(',')})`};
 const rand=(v)=>{const x=Math.sin(v*91.173+12.371)*43758.5453;return x-Math.floor(x)};
 const xy=t=>[42*t.q,Math.sqrt(3)*28*(t.r+t.q/2)];
 const vertex=(x,y,z)=>{
   let c=Math.cos(cam.yaw),s=Math.sin(cam.yaw);
   let u=x*c-y*s,v=x*s+y*c;
   const elev=cam.elevation;
   return {x:lastW/2+(u*cam.scale)+cam.shiftX,y:lastH/2+(v*Math.sin(elev)-z*Math.cos(elev))*cam.scale+cam.shiftY,depth:v*Math.cos(elev)+z*Math.sin(elev)};
 };
 function polygon(points,fill,stroke,width=1){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.lineWidth=width;ctx.strokeStyle=stroke;ctx.stroke()}}
 function line(points,color,width=1){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.lineWidth=width;ctx.strokeStyle=color;ctx.lineCap='round';ctx.lineJoin='round';ctx.stroke()}
 function dot(x,y,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.arc(x,y,r,0,TWO);ctx.fill()}
 function hexVertex(x,y,z,i,r=27){const a=i*Math.PI/3;return vertex(x+r*Math.cos(a),y+r*Math.sin(a),z)}
 function drawTile(t,idx,eligible,bases){
   const [x,y]=xy(t),d=t.d,base=bases.findIndex(b=>b.q===t.q&&b.r===t.r),owner=ownerFor(t);
   // The GWD band (radius 4) uses the same cracked, neutral masonry as the middle hexes.
    // This is visual only: game tiers, challenge assignments and ownership are unchanged.
    const type=(t.tier==='inner'&&t.d===4)?'middle':t.tier,seed=t.q*39+t.r*71+231;
   const height=type==='vault'?18:type==='key'?13:type==='inner'?11:type==='middle'?9:7;
   const r=radii[type],top=Array.from({length:6},(_,i)=>hexVertex(x,y,height,i,r)),bottom=Array.from({length:6},(_,i)=>hexVertex(x,y,0,i,r));
   const col=tints[type],chosen=selected&&selected.id===t.id,isEligible=eligible.has(t.id);
   const shade=rand(seed)*.20-.09;
   let surface=blend(col,'#bdab82',Math.max(0,shade));
   if(owner!==null)surface=blend(surface,colors[owner],.32);
   // Proper raised geometry: visible side faces are real projected 3D wall quadrilaterals.
   const faces=[];
   for(let i=0;i<6;i++){
     const j=(i+1)%6,p1=top[i],p2=top[j],b1=bottom[i],b2=bottom[j];
     const cross=(p2.x-p1.x)*(b1.y-p1.y)-(p2.y-p1.y)*(b1.x-p1.x);
     if(cross>0){faces.push({points:[p1,p2,b2,b1],depth:(p1.depth+p2.depth+b1.depth+b2.depth)/4,i})}
   }
   faces.sort((a,b)=>a.depth-b.depth);
   for(const f of faces)polygon(f.points,blend('#2b3028',col,.36+f.i*.025),'#181e1a',.7);
   if(type==='inner'||type==='vault'){
     ctx.save();ctx.shadowBlur=(type==='vault'?17:8)*cam.scale;ctx.shadowColor=type==='vault'?'#a769fa':'#83d0b8';polygon(top,blend(surface,'#9baf99',.09),'#9cbbab',1.35*cam.scale);ctx.restore();
   }
   polygon(top,surface,owner!==null?colors[owner]:type==='vault'?'#b28bd4':type==='key'?'#b3b088':'#393a30',Math.max(.7,(owner!==null?2.3:1)*cam.scale));
   // Hairline top-left bevel catches the light across all tiles.
   line([top[3],top[4],top[5]],'#d4c7a73d',Math.max(.55,cam.scale*.9));
   ctx.save();ctx.beginPath();top.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.clip();
   const pts=(fraction)=>vertex(x+fraction[0],y+fraction[1],height+.1);
   if(type==='outer'){
     // Foliage grows from each tile edge into cracked corners; more common toward the perimeter.
     const coverage=.56+d*.033;
     for(let k=0;k<10;k++){
       let a=rand(seed+k*19)*TWO,rr=(.56+.37*rand(seed+k*13))*r;
       let P=pts([Math.cos(a)*rr,Math.sin(a)*rr]);
       if(rand(seed+k*17)<coverage){dot(P.x,P.y,clamp(cam.scale* (1.4+2.7*rand(seed+k*23)),.65,5),k%3?'#304c31aa':'#778b4aac')}
     }
     for(let k=0;k<3;k++){let P=pts([Math.cos(k*2.3+seed)*r*.7,Math.sin(k*2.3+seed)*r*.7]);line([P,pts([Math.cos(k*2.3+seed)*r*.2,Math.sin(k*2.3+seed)*r*.2])],'#303c2aaa',.8*cam.scale)}
   }
   if(type==='middle'||type==='inner'||type==='vault'){
     const count=type==='middle'?2:3;
     for(let k=0;k<count;k++){
       let angle=(rand(seed+k*9)-.5)*2.1, yy=(k-1)*7.5;
       const coords=[[-r*.74,yy],[ -r*.29,yy+4],[3,yy-1],[r*.37,yy+6],[r*.79,yy+3]].map(([a,b])=>pts([a*Math.cos(angle)-b*Math.sin(angle),a*Math.sin(angle)+b*Math.cos(angle)]));
       line(coords,type==='middle'?'#302e288a':'#37302aa6',type==='middle'?1.7*cam.scale:1.3*cam.scale);
       if(type==='inner'||type==='vault'){ctx.save();ctx.shadowBlur=8*cam.scale;ctx.shadowColor=type==='vault'?'#a24dff':'#60d8c7';line(coords,type==='vault'?'#b57cffbb':'#79cdb3a0',.8*cam.scale);ctx.restore()}
     }
   }
   if(type==='key'){
     const discovered=canRevealKey(t),tooth=discovered&&keyHalf(t)==='tooth',a=pts([0,0]);
     ctx.save();ctx.shadowBlur=12*cam.scale;ctx.shadowColor=!discovered?'#c8b48a':tooth?'#43b9bc':'#a5cff2';dot(a.x,a.y,11*cam.scale,!discovered?'#9b8d6766':tooth?'#317c8d66':'#a5c7d566');ctx.restore();
     polygon(Array.from({length:6},(_,i)=>hexVertex(x,y,height+.3,i,r*.68)),null,!discovered?'#c6b895':tooth?'#71cbd7':'#d9d8cb',1.6*cam.scale);
     ctx.font=`${Math.max(10,16*cam.scale)}px Georgia`;ctx.fillStyle=!discovered?'#e0d0a4':tooth?'#92edf0':'#cbdfff';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(!discovered?'?':tooth?'≈':'❄',a.x,a.y);
   }
   if(type==='vault'){
     const center=vertex(x,y,height+1),rr=14*cam.scale;
     ctx.save();ctx.shadowColor='#b56cfb';ctx.shadowBlur=23*cam.scale;dot(center.x,center.y,rr,'#7842a0aa');ctx.restore();
     polygon(Array.from({length:6},(_,i)=>hexVertex(x,y,height+1,i,r*.62)),'#503b69','#d5a2ff',2*cam.scale);
     ctx.fillStyle='#e5c2ff';ctx.font=`bold ${Math.max(12,24*cam.scale)}px Georgia`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('✦',center.x,center.y);
   }
   if(base>=0){const center=vertex(x,y,height+.2);ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`bold ${Math.max(7,11*cam.scale)}px Arial`;ctx.fillStyle='#f9e8b3';ctx.fillText('BASE '+(base+1),center.x,center.y)}
   if(chosen||isEligible){polygon(top,null,chosen?'#fff0b1':colors[viewTeam],Math.max(1.7,3.2*cam.scale))}
   ctx.restore();
   visiblePolys.push({tile:t,points:top});
 }
 function draw(){
   if(!document.body.contains(canvas))return;
   const box=viewport.getBoundingClientRect();if(box.width<1||box.height<1)return;
   const dpr=Math.min(window.devicePixelRatio||1,2),w=box.width,h=box.height;
   lastW=w;lastH=h;
   if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr)}
   ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);
   const scale=clamp(Math.min((w-24)/780,(h-60)/630)*cam.zoom,.15,3.5);cam.scale=scale;
   const bases=teamBases(),eligible=eligibleSet(viewTeam);visiblePolys=[];
   // An orthographic, azimuth/tilt camera; tiles are separately extruded volumes.
   const ordered=tiles.map((t,i)=>{const [x,y]=xy(t);return {t,i,depth:vertex(x,y,0).depth}}).sort((a,b)=>a.depth-b.depth);
   for(const item of ordered)drawTile(item.t,item.i,eligible,bases);
 }
 const inside=(pt,x,y)=>{let yes=false;for(let i=0,j=pt.length-1;i<pt.length;j=i++){const a=pt[i],b=pt[j];if(((a.y>y)!==(b.y>y))&&(x<(b.x-a.x)*(y-a.y)/(b.y-a.y)+a.x))yes=!yes}return yes};
 function setAngles(yaw,elevation){cam.yaw=yaw;cam.elevation=clamp(elevation,.35,Math.PI/2);draw()}
 function resetCamera(){cam.yaw=initial.yaw;cam.elevation=initial.elevation;cam.zoom=1;cam.shiftX=0;cam.shiftY=0;document.getElementById("view3dButton").textContent="2D";draw()}
 function pointerPoint(e){const rect=canvas.getBoundingClientRect();return [e.clientX-rect.left,e.clientY-rect.top]}
 const tracked=new Map();
 // Capture phase intercepts old SVG pan listeners only when using the new 3D camera.
 viewport.addEventListener('pointerdown',e=>{if(e.target!==canvas)return;e.stopImmediatePropagation();canvas.focus({preventScroll:true});tracked.set(e.pointerId,pointerPoint(e));drag3={x:e.clientX,y:e.clientY,yaw:cam.yaw,elevation:cam.elevation,shiftX:cam.shiftX,shiftY:cam.shiftY,zoom:cam.zoom,moved:false,button:e.button};canvas.setPointerCapture(e.pointerId)},true);
 viewport.addEventListener('pointermove',e=>{if(!tracked.has(e.pointerId))return;e.stopImmediatePropagation();const next=pointerPoint(e),prev=tracked.get(e.pointerId);tracked.set(e.pointerId,next);if(!drag3)return;
   if(tracked.size>=2){const pts=[...tracked.values()];const delta=Math.hypot(pts[0][0]-pts[1][0],pts[0][1]-pts[1][1]);if(drag3.lastPinch)cam.zoom=clamp(cam.zoom*delta/drag3.lastPinch,.55,3);drag3.lastPinch=delta;drag3.moved=true;draw();return}
   const dx=e.clientX-drag3.x,dy=e.clientY-drag3.y;if(Math.hypot(dx,dy)>4)drag3.moved=true;
   if(!drag3.moved)return;
   if(e.button===2||drag3.button===2||e.shiftKey){cam.shiftX=drag3.shiftX+dx;cam.shiftY=drag3.shiftY+dy}else{cam.yaw=drag3.yaw+dx*.008;cam.elevation=clamp(drag3.elevation-dy*.005,.35,Math.PI/2)}draw()
 },true);
 viewport.addEventListener('pointerup',e=>{if(!tracked.has(e.pointerId))return;e.stopImmediatePropagation();tracked.delete(e.pointerId);if(!drag3?.moved){const [x,y]=pointerPoint(e);for(let i=visiblePolys.length-1;i>=0;i--)if(inside(visiblePolys[i].points,x,y)){selectTile(visiblePolys[i].tile);break}}drag3=null},true);
 viewport.addEventListener('pointercancel',e=>{tracked.delete(e.pointerId);drag3=null},true);
 viewport.addEventListener('wheel',e=>{if(e.target!==canvas)return;e.preventDefault();e.stopImmediatePropagation();cam.zoom=clamp(cam.zoom*(e.deltaY<0?1.12:.89),.55,3);draw()},{capture:true,passive:false});
 canvas.addEventListener('contextmenu',e=>e.preventDefault());
 for(const [id,change] of [['zoomIn',1.18],['zoomOut',1/1.18]])document.getElementById(id)?.addEventListener('click',e=>{e.stopImmediatePropagation();cam.zoom=clamp(cam.zoom*change,.55,3);draw()},true);
 document.getElementById('fitButton')?.addEventListener('click',e=>{e.stopImmediatePropagation();resetCamera()},true);
 document.getElementById('view3dButton')?.addEventListener('click',e=>{e.stopImmediatePropagation();const overhead=cam.elevation>1.48;setAngles(overhead?initial.yaw:0,overhead?initial.elevation:Math.PI/2);e.currentTarget.textContent=overhead?'2D':'3D'},true);
 window.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;if(/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName||''))return;e.preventDefault();if(e.key==='ArrowLeft')cam.yaw-=.11;if(e.key==='ArrowRight')cam.yaw+=.11;if(e.key==='ArrowUp')cam.elevation+=.09;if(e.key==='ArrowDown')cam.elevation-=.09;cam.elevation=clamp(cam.elevation,.35,Math.PI/2);draw()});
 const feed=document.getElementById('journalFeed'),latest=document.getElementById('journalLatest');
 if(feed){let programmatic=false;feed.dataset.follow='true';feed.addEventListener('scroll',()=>{if(programmatic)return;feed.dataset.follow=feed.scrollHeight-feed.scrollTop-feed.clientHeight<40?'true':'false'},{passive:true});if(latest)latest.onclick=()=>{programmatic=true;feed.scrollTop=feed.scrollHeight;feed.dataset.follow='true';requestAnimationFrame(()=>programmatic=false)}}
 window.__xodus3d={draw,resetCamera,setAngles,cam};
 window.addEventListener('resize',()=>requestAnimationFrame(draw));
 requestAnimationFrame(draw);
})();

